mapper.select:
/*selectMasterWmPgPrewarhsngWarhsngRegList*/
SELECT X.STATUS_TEXT , X.BS_NO /* 선입고 요청번호 */ , X.BEFORE_GR_DATE /* 요청일자 */ , X.ADD_DATE , TO_CHAR(SYSDATE,'YYYYMMDD') AS GR_DATE , X.BUYER_NAME , X.AGENT_NAME || '(' || X.AGENT_TEL_NO || ')' AS AGENT_INFO , X.AGENT_NAME , X.AGENT_TEL_NO , X.MAKER_NAME , X.BUYER_ITEM_NO , X.DESCRIPTION , X.SPECIFICATION , X.ITEM_QTY , X.INV_QTY , X.INV_QTY AS GR_QTY , X.UNIT_MEASURE , X.UNIT_PRICE , X.INV_QTY * X.UNIT_PRICE AS UNIT_AMT , X.AGENT_PRICE , X.INV_QTY * X.AGENT_PRICE AS AGENT_AMT , X.DELY_TO_LOCATION , X.REQ_USER_NAME || '(' || X.REQ_USER_TEL_NO || ')' AS REQ_USER_INFO , X.REQ_USER_NAME , X.REQ_USER_TEL_NO , X.BOX_QTY , X.SCHEDULED_DATE , X.CAR_ID , X.CAR_NO , X.CAR_PERSON_NAME , X.CAR_PERSON_TEL , X.BUYER_CODE /* 히든필드 */ , X.AGENT_CODE /* 히든필드 */ , X.WAREHOUSE_CODE /* 히든필드 */ , X.INV_NO /* 히든필드 */ , X.INV_SEQ /* 히든필드 */ , X.CONTRACT_NO /* 히든필드 */ , X.CONTRACT_SEQ /* 히든필드 */ FROM ( SELECT (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE=A.BUYER) AS BUYER_NAME , A.BEFORE_GR_DATE AS BEFORE_GR_DATE , A.PO_NO AS PO_NO , A.BUYER_ITEM_NO AS BUYER_ITEM_NO , A.DESCRIPTION AS DESCRIPTION , A.MAKER_NAME AS MAKER_NAME , A.UNIT_PRICE AS UNIT_PRICE , A.ITEM_QTY , A.REQ_USER_NAME , A.REQ_USER_DEPT_NAME , A.REQ_USER_TEL_NO , A.AGENT_NAME , A.AGENT_USER_NAME , A.AGENT_TEL_NO , A.KEP_USER_NAME , A.SPECIFICATION , A.ORIGIN_NAME , A.AGENT_PRICE , A.UNIT_MEASURE , A.BS_NO , A.BUYER AS BUYER_CODE , A.CLOSE_ITEM_QTY , A.DELIVERY_FLAG , A.PROCESS_TYPE , A.DELY_TO_LOCATION , A.REQ_USER_ID , A.REQ_USER_DEPT_CODE , A.MAKER_CODE , A.ORIGIN_CODE , A.AGENT_CODE , A.AGENT_USER_ID , A.KEP_USER_ID , CASE WHEN A.STATUS = 'D' THEN 'BS99' /* 선입고취소 */ WHEN A.DELIVERY_FLAG = 'Y' THEN 'BS40' /* 납품확정 */ WHEN A.DELIVERY_FLAG = 'P' THEN 'BS30' /* 납품예정 */ WHEN B.INV_NO IS NOT NULL THEN 'BS20' /* 입고예정 */ WHEN B.INV_NO IS NULL THEN 'BS10' /* 요청 */ ELSE NULL END AS STATUS , CASE WHEN A.STATUS = 'D' THEN '선입고취소' WHEN A.DELIVERY_FLAG = 'Y' THEN '납품확정' WHEN A.DELIVERY_FLAG = 'P' THEN '납품예정' WHEN B.INV_NO IS NOT NULL THEN '입고예정' WHEN B.INV_NO IS NULL THEN '요청' ELSE NULL END AS STATUS_TEXT , B.ADD_DATE , B.INV_QTY , CASE WHEN B.SCHEDULED_DATE IS NULL OR B.SCHEDULED_DATE = '' THEN TO_CHAR( ( CASE WHEN (SYSDATE+7)-NEXT_DAY(SYSDATE,1)+1 = 6 THEN SYSDATE+3 WHEN (SYSDATE+7)-NEXT_DAY(SYSDATE,1)+1 = 7 THEN SYSDATE+2 ELSE SYSDATE+1 END ), 'YYYYMMDD') ELSE B.SCHEDULED_DATE END SCHEDULED_DATE , NVL(C.CAR_ID,'') CAR_ID , NVL(C.CAR_NO,'') CAR_NO , NVL(C.CAR_PERSON_NAME,'') CAR_PERSON_NAME , NVL(C.CAR_PERSON_TEL,'') CAR_PERSON_TEL , CASE WHEN B.BOX_QTY IS NULL OR B.BOX_QTY = 0 THEN 1 ELSE B.BOX_QTY END BOX_QTY , A.WAREHOUSE_CODE , B.INV_NO , B.INV_SEQ , A.CONTRACT_NO , A.CONTRACT_SEQ FROM KEP_BEFORE_STOCKED_MNG A /* 선입고관리 */ , KEP_BEFORE_STOCKED_IVDT B /* 선입고송장상세 */ , ( SELECT CAR_ID , CAR_NO , CAR_PERSON_NAME , CAR_PERSON_TEL , BASE_YN , BUYER FROM BNTBUYERCARINFO WHERE BASE_YN = 'Y' ) C WHERE 1=1 AND A.BUYER = B.BUYER AND A.BS_NO = B.BS_NO AND A.BUYER = C.BUYER(+) AND A.BEFORE_GR_DATE >= #{st_from_date} AND A.BEFORE_GR_DATE <= #{st_to_date}
AND A.BUYER IN
#{item}
AND A.AGENT_CODE = #{st_agent_code}
AND A.WAREHOUSE_CODE = #{st_warehouse_code}
AND A.BS_NO LIKE '%' || #{st_bs_no} || '%'
AND A.BUYER_ITEM_NO LIKE '%' || #{st_buyer_item_no} || '%'
AND A.DESCRIPTION LIKE '%' || #{st_buyer_item_name} || '%'
AND A.PROCESS_TYPE = '2' /* TR */ AND B.WMS_GR_QTY = 0 ORDER BY A.BUYER , A.BS_NO DESC ) X

/*selectMasterWmPgPrewarhsngWarhsngReg_Check_Yn*/

		SELECT
		    DECODE(COUNT(*), 0, 'Y', 'N') AS CHECK_YN
		FROM
		    KEP_BEFORE_STOCKED_IVDT /* 선입고송장상세 */
		WHERE 1=1
		AND INV_NO = #{INV_NO}
		AND INV_SEQ = #{INV_SEQ}
		AND BUYER = #{BUYER_CODE}
		AND BS_NO = #{BS_NO}
		AND STATUS <> 'D'
		AND WMS_GR_QTY <> 0 /* 입고가 진행된 경우 */

mapper.update:
/*updateMasterWmPgPrewarhsngWarhsngReg_WMS_GR_QTY*/

		UPDATE KEP_BEFORE_STOCKED_IVDT /* 선입고송장상세 */
		SET WMS_GR_QTY = NVL(INV_QTY, 0)
		  , WMS_GR_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD')
		  , WMS_GR_USER_ID = #{st_user_id}
		  , BOX_QTY = #{BOX_QTY}
		  , SCHEDULED_DATE = #{SCHEDULED_DATE} /* 출고예정일 */
		  , CAR_ID = #{CAR_ID}
		  , CAR_NO = #{CAR_NO}
		  , CAR_PERSON_NAME = #{CAR_PERSON_NAME}
		  , CAR_PERSON_TEL = #{CAR_PERSON_TEL}
		WHERE 1=1
		AND INV_NO = #{INV_NO}
		AND INV_SEQ = #{INV_SEQ}
		AND BUYER = #{BUYER_CODE}
		AND BS_NO = #{BS_NO}
		AND STATUS <> 'D'
		AND WMS_GR_QTY = 0

/*updateMasterWmPgPrewarhsngWarhsngReg_GR_QTY*/

		UPDATE KEP_BEFORE_STOCKED_MNG /* 선입고관리 */
		SET GR_QTY = #{INV_QTY} /* 물류센터 입고수량 */
		WHERE 1=1
		AND BUYER = #{BUYER_CODE}
		AND BS_NO = #{BS_NO}

/*updateMasterWmPgPrewarhsngWarhsngReg_IV_QTY*/

		UPDATE KEP_BEFORE_STOCKED_MNG /* 선입고관리 */
		SET IV_QTY = #{INV_QTY} /* 물류센터 출고수량 */
		  , DELIVERY_FLAG = 'Y'
		WHERE 1=1
		AND BUYER = #{BUYER_CODE}
		AND BS_NO = #{BS_NO}
